import React, { useEffect, useState } from 'react';
import { getStudents } from '../api/api';

function StudentList({ onViewResult }) {
  const [students, setStudents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchStudents();
  }, []);

  async function fetchStudents() {
    setLoading(true);
    setError(null);
    try {
      const data = await getStudents();
      setStudents(data);
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }

  if (loading) return <div className="state-message">Loading students...</div>;
  if (error) return <div className="state-message error">{error} <button onClick={fetchStudents}>Retry</button></div>;
  if (students.length === 0) return <div className="state-message">No students added yet. Add one to get started.</div>;

  return (
    <div className="card">
      <div className="card-header-row">
        <h2>Students</h2>
        <button className="btn-secondary" onClick={fetchStudents}>Refresh</button>
      </div>
      <div className="table-wrapper">
        <table>
          <thead>
            <tr>
              <th>Roll No</th>
              <th>Name</th>
              <th>Class</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {students.map((s) => (
              <tr key={s.id}>
                <td>{s.roll_no}</td>
                <td>{s.name}</td>
                <td>{s.class}</td>
                <td>
                  <button className="btn-link" onClick={() => onViewResult(s.id)}>View Result</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default StudentList;
